            },
            './common/autoStart.js': { triggerSmIfIdle: function () { } },
            './common/outputFiles.js': { readOutputFile: function () { return null; } },
            './cacheToReleases.js': {},
            './common/gitStaging.js': gitStagingModuleLocal,
