        file_read: sharedFileRead
    });

    var mod = loadModule(
        'js/developBugAndCreatePR.js',
        makeRequire({
            './config.js': configModule,
            './common/gitStaging.js': gitStagingModuleLocal,
            './configLoader.js': configLoaderModule,
            './common/outputFiles.js': realOutputFiles,
